"""Detection report export and file download endpoints."""

from pathlib import Path
from fastapi import APIRouter, Depends, HTTPException, status
from fastapi.responses import FileResponse
from sqlalchemy.orm import Session

from src.api.deps import get_db_session
from src.database.crud.prediction_repo import get_prediction_job_by_id

router = APIRouter(prefix="/api/v1/export", tags=["Reports & Export"])


@router.get("/report/{job_id}/csv")
def download_detection_report(
    job_id: int,
    db: Session = Depends(get_db_session),
):
    """Downloads the full annotated CSV report generated by a batch prediction job."""
    job = get_prediction_job_by_id(db, job_id)
    if not job:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Prediction job with ID {job_id} not found.",
        )

    if not job.report_csv_path or not Path(job.report_csv_path).exists():
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Report file missing from disk: {job.report_csv_path}",
        )

    file_path = Path(job.report_csv_path)
    return FileResponse(
        path=str(file_path),
        filename=file_path.name,
        media_type="text/csv",
    )


@router.get("/report/{job_id}/summary")
def get_report_summary(
    job_id: int,
    db: Session = Depends(get_db_session),
):
    """Retrieves an executive summary of the prediction run."""
    job = get_prediction_job_by_id(db, job_id)
    if not job:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Prediction job with ID {job_id} not found.",
        )

    return {
        "job_id": job.id,
        "dataset_id": job.dataset_id,
        "model_id": job.model_experiment_id,
        "total_records": job.total_records,
        "normal_count": job.normal_count,
        "malicious_count": job.malicious_count,
        "detection_rate": job.detection_rate,
        "execution_time_seconds": job.execution_time_seconds,
        "status": job.status,
        "created_at": job.created_at.isoformat() if job.created_at else None,
    }
